using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;

namespace ElectronicsStore.Api.Data;

public sealed class StoreDbContext(DbContextOptions<StoreDbContext> options) : DbContext(options)
{
    public DbSet<Category> Categories => Set<Category>();
    public DbSet<Brand> Brands => Set<Brand>();
    public DbSet<AdminUser> AdminUsers => Set<AdminUser>();
    public DbSet<MediaAsset> MediaAssets => Set<MediaAsset>();
    public DbSet<Product> Products => Set<Product>();
    public DbSet<ProductVariant> ProductVariants => Set<ProductVariant>();
    public DbSet<ProductImage> ProductImages => Set<ProductImage>();
    public DbSet<ProductSpecification> ProductSpecifications => Set<ProductSpecification>();
    public DbSet<ProductCompatibility> ProductCompatibility => Set<ProductCompatibility>();
    public DbSet<ShippingZone> ShippingZones => Set<ShippingZone>();
    public DbSet<StoreSetting> StoreSettings => Set<StoreSetting>();
    public DbSet<StoreSocialLink> StoreSocialLinks => Set<StoreSocialLink>();
    public DbSet<HeroSlide> HeroSlides => Set<HeroSlide>();
    public DbSet<StoreOrder> Orders => Set<StoreOrder>();
    public DbSet<OrderItem> OrderItems => Set<OrderItem>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.HasDefaultSchema("public");
        modelBuilder.Entity<Category>(e => { e.ToTable("categories", t => { t.HasCheckConstraint("categories_name_check", "length(btrim(name)) > 0"); t.HasCheckConstraint("categories_slug_check", "length(btrim(slug)) > 0"); t.HasCheckConstraint("categories_sort_order_check", "sort_order >= 0"); }); e.HasKey(x => x.Id); e.HasIndex(x => x.Slug).IsUnique(); e.HasIndex(x => new { x.IsActive, x.SortOrder }); e.Property(x => x.Id).HasDefaultValueSql("gen_random_uuid()"); e.Property(x => x.CreatedAt).HasDefaultValueSql("now()"); e.Property(x => x.UpdatedAt).HasDefaultValueSql("now()"); });
        modelBuilder.Entity<Brand>(e => { e.ToTable("brands"); e.HasKey(x => x.Id); e.HasIndex(x => x.Name).IsUnique().HasDatabaseName("brands_name_lower_uq").HasFilter(null); e.Property(x => x.Id).HasDefaultValueSql("gen_random_uuid()"); e.Property(x => x.CreatedAt).HasDefaultValueSql("now()"); e.Property(x => x.UpdatedAt).HasDefaultValueSql("now()"); });
        modelBuilder.Entity<AdminUser>(e => { e.ToTable("admin_users"); e.HasKey(x => x.Id); e.HasIndex(x => x.Email).IsUnique().HasDatabaseName("admin_users_email_lower_uq"); e.Property(x => x.Id).HasDefaultValueSql("gen_random_uuid()"); e.Property(x => x.Role).HasDefaultValue("admin"); e.Property(x => x.IsActive).HasDefaultValue(true); e.Property(x => x.CreatedAt).HasDefaultValueSql("now()"); e.Property(x => x.UpdatedAt).HasDefaultValueSql("now()"); });
        modelBuilder.Entity<MediaAsset>(e => { e.ToTable("media_assets"); e.HasKey(x => x.Id); e.HasIndex(x => new { x.BucketId, x.ObjectPath }).IsUnique(); e.Property(x => x.Id).HasDefaultValueSql("gen_random_uuid()"); e.Property(x => x.BucketId).HasDefaultValue("store-media"); e.Property(x => x.CreatedAt).HasDefaultValueSql("now()"); e.HasOne(x => x.UploadedByAdmin).WithMany().HasForeignKey(x => x.UploadedByAdminId).OnDelete(DeleteBehavior.SetNull); });
        modelBuilder.Entity<Product>(e => { e.ToTable("products"); e.HasKey(x => x.Id); e.HasIndex(x => x.Slug).IsUnique(); e.HasIndex(x => x.CategoryId); e.HasIndex(x => x.BrandId); e.HasIndex(x => new { x.CategoryId, x.BrandId }); e.HasIndex(x => x.CreatedAt); e.HasIndex(x => x.Price); e.HasIndex(x => x.Popularity); e.HasIndex(x => x.Stock); e.Property(x => x.Id).HasDefaultValueSql("gen_random_uuid()"); e.Property(x => x.Price).HasPrecision(12, 2); e.Property(x => x.DiscountPrice).HasPrecision(12, 2); e.Property(x => x.Description).HasDefaultValue(""); e.Property(x => x.Popularity).HasDefaultValue(0); e.Property(x => x.IsUniversalCompatible).HasDefaultValue(false); e.Property(x => x.CreatedAt).HasDefaultValueSql("now()"); e.Property(x => x.UpdatedAt).HasDefaultValueSql("now()"); e.HasOne(x => x.Category).WithMany(x => x.Products).HasForeignKey(x => x.CategoryId).OnDelete(DeleteBehavior.Restrict); e.HasOne(x => x.Brand).WithMany(x => x.Products).HasForeignKey(x => x.BrandId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<ProductVariant>(e => { e.ToTable("product_variants"); e.HasKey(x => x.Id); e.HasAlternateKey(x => new { x.Id, x.ProductId }); e.HasIndex(x => new { x.ProductId, x.SortOrder }); e.HasIndex(x => new { x.ProductId, x.Label }).IsUnique(); e.Property(x => x.Id).HasDefaultValueSql("gen_random_uuid()"); e.Property(x => x.Price).HasPrecision(12, 2); e.Property(x => x.DiscountPrice).HasPrecision(12, 2); e.Property(x => x.Stock).HasDefaultValue(0); e.Property(x => x.SortOrder).HasDefaultValue(0); e.Property(x => x.CreatedAt).HasDefaultValueSql("now()"); e.Property(x => x.UpdatedAt).HasDefaultValueSql("now()"); e.HasOne(x => x.Product).WithMany(x => x.Variants).HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Cascade); });
        modelBuilder.Entity<ProductImage>(e => { e.ToTable("product_images"); e.HasKey(x => x.Id); e.HasIndex(x => new { x.ProductId, x.SortOrder }).IsUnique(); e.Property(x => x.Id).HasDefaultValueSql("gen_random_uuid()"); e.Property(x => x.CreatedAt).HasDefaultValueSql("now()"); e.HasOne(x => x.Product).WithMany(x => x.Images).HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Cascade); e.HasOne(x => x.MediaAsset).WithMany().HasForeignKey(x => x.MediaAssetId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<ProductSpecification>(e => { e.ToTable("product_specifications"); e.HasKey(x => x.Id); e.HasIndex(x => new { x.ProductId, x.SortOrder }).IsUnique(); e.Property(x => x.Id).HasDefaultValueSql("gen_random_uuid()"); e.HasOne(x => x.Product).WithMany(x => x.Specifications).HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Cascade); });
        modelBuilder.Entity<ProductCompatibility>(e => { e.ToTable("product_compatibility"); e.HasKey(x => new { x.AccessoryProductId, x.DeviceProductId }); e.HasIndex(x => new { x.DeviceProductId, x.AccessoryProductId }); e.Property(x => x.CreatedAt).HasDefaultValueSql("now()"); e.HasOne<Product>().WithMany().HasForeignKey(x => x.AccessoryProductId).OnDelete(DeleteBehavior.Cascade); e.HasOne<Product>().WithMany().HasForeignKey(x => x.DeviceProductId).OnDelete(DeleteBehavior.Cascade); });
        modelBuilder.Entity<ShippingZone>(e => { e.ToTable("shipping_zones"); e.HasKey(x => x.Id); e.HasIndex(x => x.Label).IsUnique(); e.HasIndex(x => new { x.IsActive, x.SortOrder }); e.Property(x => x.Id).HasDefaultValueSql("gen_random_uuid()"); e.Property(x => x.Fee).HasPrecision(12, 2).HasDefaultValue(0m); e.Property(x => x.CreatedAt).HasDefaultValueSql("now()"); e.Property(x => x.UpdatedAt).HasDefaultValueSql("now()"); });
        modelBuilder.Entity<StoreSetting>(e => { e.ToTable("store_settings"); e.HasKey(x => x.Id); e.Property(x => x.Id).HasDefaultValue((short)1); e.Property(x => x.StoreName).HasDefaultValue("المتجر"); e.Property(x => x.Tagline).HasDefaultValue(""); e.Property(x => x.WhatsappEnabled).HasDefaultValue(false); e.Property(x => x.WhatsappMessage).HasDefaultValue(""); e.Property(x => x.BannerEnabled).HasDefaultValue(false); e.Property(x => x.BannerText).HasDefaultValue(""); e.Property(x => x.ShowOutOfStock).HasDefaultValue(false); e.Property(x => x.ThemeColor).HasDefaultValue("oklch(0.45 0.11 205)"); e.Property(x => x.PolicyShipping).HasDefaultValue(""); e.Property(x => x.PolicyWarranty).HasDefaultValue(""); e.Property(x => x.PolicyReturns).HasDefaultValue(""); e.Property(x => x.PolicyPrivacy).HasDefaultValue(""); e.Property(x => x.UpdatedAt).HasDefaultValueSql("now()"); });
        modelBuilder.Entity<StoreSocialLink>(e => { e.ToTable("store_social_links"); e.HasKey(x => x.Id); e.HasIndex(x => x.SortOrder); e.Property(x => x.Id).HasDefaultValueSql("gen_random_uuid()"); });
        modelBuilder.Entity<HeroSlide>(e => { e.ToTable("hero_slides"); e.HasKey(x => x.Id); e.HasIndex(x => new { x.IsActive, x.SortOrder }); e.Property(x => x.Id).HasDefaultValueSql("gen_random_uuid()"); e.Property(x => x.Badge).HasDefaultValue(""); e.Property(x => x.BodyText).HasDefaultValue(""); e.Property(x => x.CtaText).HasDefaultValue(""); e.Property(x => x.Link).HasDefaultValue(""); e.Property(x => x.CreatedAt).HasDefaultValueSql("now()"); e.Property(x => x.UpdatedAt).HasDefaultValueSql("now()"); e.HasOne(x => x.MediaAsset).WithMany().HasForeignKey(x => x.MediaAssetId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<StoreOrder>(e => { e.ToTable("orders"); e.HasKey(x => x.Id); e.HasIndex(x => x.OrderNumber).IsUnique(); e.HasIndex(x => x.CreatedAt); e.HasIndex(x => new { x.Status, x.CreatedAt }); e.HasIndex(x => x.CustomerPhone); e.Property(x => x.Id).HasDefaultValueSql("gen_random_uuid()"); e.Property(x => x.ShippingFee).HasPrecision(12, 2); e.Property(x => x.Subtotal).HasPrecision(12, 2); e.Property(x => x.Total).HasPrecision(12, 2); e.Property(x => x.CurrencyCode).HasColumnType("character(3)").HasDefaultValue("ILS"); e.Property(x => x.PaymentMethod).HasDefaultValue("cash_on_delivery"); e.Property(x => x.Status).HasDefaultValue("Pending"); e.Property(x => x.CustomerNotes).HasDefaultValue(""); e.Property(x => x.CreatedAt).HasDefaultValueSql("now()"); e.Property(x => x.UpdatedAt).HasDefaultValueSql("now()"); e.HasOne(x => x.ShippingZone).WithMany().HasForeignKey(x => x.ShippingZoneId).OnDelete(DeleteBehavior.SetNull); });
        modelBuilder.Entity<OrderItem>(e => { e.ToTable("order_items"); e.HasKey(x => x.Id); e.HasIndex(x => x.OrderId); e.HasIndex(x => x.ProductId); e.Property(x => x.Id).HasDefaultValueSql("gen_random_uuid()"); e.Property(x => x.UnitPrice).HasPrecision(12, 2); e.Property(x => x.LineTotal).HasComputedColumnSql("unit_price * quantity", stored: true); e.Property(x => x.CreatedAt).HasDefaultValueSql("now()"); e.HasOne(x => x.Order).WithMany(x => x.Items).HasForeignKey(x => x.OrderId).OnDelete(DeleteBehavior.Cascade); e.HasOne<Product>().WithMany().HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.SetNull); e.HasOne<ProductVariant>().WithMany().HasForeignKey(x => new { x.VariantId, x.ProductId }).HasPrincipalKey(x => new { x.Id, x.ProductId }).OnDelete(DeleteBehavior.SetNull); });

        foreach (var entity in modelBuilder.Model.GetEntityTypes())
            foreach (var property in entity.GetProperties())
                property.SetColumnName(ToSnakeCase(property.Name));
    }

    private static string ToSnakeCase(string value) => string.Concat(value.Select((c, i) => i > 0 && char.IsUpper(c) ? "_" + char.ToLowerInvariant(c) : char.ToLowerInvariant(c).ToString()));
}
